import { Schema, model } from 'mongoose';

const UserSchema = new Schema({
  name: {
    type: String,
    required: [true, 'product name required'],
  },
  email: {
    type: String,
    required: [true, 'email required'],
  },
  //month-day-year
  DOB: {
    type: Date,
    required: [true, 'date of birth is required'],
  },
  mobilenumber: {
    type: Number,
    required:[true,'mobile number is required'],
  },
  status:{
    type:Boolean,
    default:true
  }
}, {
  timestamps: true,
  versionKey:false,
  strict:"throw"
});

// Configure partial unique indexes so unique constraint only applies to active users
UserSchema.index({ email: 1 }, { unique: true, partialFilterExpression: { status: true } });
UserSchema.index({ mobilenumber: 1 }, { unique: true, partialFilterExpression: { status: true } });

export const UserModel = model('user', UserSchema);

